#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> a(n);
    for (int& x : a) cin >> x;

    long long ans = 0;

    for (int i = 1; i < n; ++i) {
        if ((a[i - 1] == 2 && a[i] == 3) ||
            (a[i - 1] == 3 && a[i] == 2)) {
            cout << "Infinite\n";
            return 0;
        }

        if (a[i - 1] == 1 && a[i] == 2 ||
            a[i - 1] == 2 && a[i] == 1) {
            ans += 3;
        } else if (a[i - 1] == 1 && a[i] == 3 ||
                   a[i - 1] == 3 && a[i] == 1) {
            ans += 4;
        }

        if (i >= 2 && a[i - 2] == 3 && a[i - 1] == 1 && a[i] == 2) {
            --ans;
        }
    }

    cout << "Finite\n" << ans << '\n';
    return 0;
}

